  ('803ea20a-0ba3-5550-ae7a-ad894e7efe29', 'roles_involved', 'Who is involved in this work today?', 'One row per person or role. Rough hours are fine.', 'Your team', 'tool_rows', null, false, $j${"columns":[{"id":"role","label":"Person or role","placeholder":"e.g. Program assistant"},{"id":"does","label":"What they do","placeholder":"e.g. Picks posts, schedules them"},{"id":"hours","label":"Hours / week","placeholder":"e.g. 6"}],"min_rows":1}$j$::jsonb),
  ('5e0dbb6c-03d2-5e3e-a62c-067f436082a6', 'decision_maker', 'Who makes the final call on changes to tools or process?', null, 'Your team', 'text', null, true, $j${}$j$::jsonb),
