  ('4b9e07ef-7a20-502c-bf9a-d18357bd193e', 'ai_how_often', 'How often is AI part of the work?', null, 'AI today', 'single', $j$["Rarely — a few experiments","Weekly, by one or two people","Daily, by one or two people","Most of the team, most days"]$j$::jsonb, false, $j${}$j$::jsonb),
