  ('7fc5cb32-6ff5-54af-8679-516496ebc3a8', 'tried_before', 'What have you already tried to fix this?', 'Tools, templates, automations, volunteers, consultants — anything.', 'What you''ve tried', 'textarea', null, true, $j${}$j$::jsonb),
