insert into crm.discovery_templates (id, name, description, intro_text, estimated_minutes, sections, is_default) values
  ('855b74c5-d0f2-5b3a-8953-6661e2eaea1f', 'Standard Discovery', 'The original v1 questionnaire. Workflow sections depend on the project type.', 'This helps me understand what you have in place today — tools, people, what you''ve tried — so our call can focus on solutions. It takes about 15 minutes and saves as you go, so you can stop and come back with the same link.', 15, $j$[{"id":"project","title":"Your project","intro":"Here's what you shared about the project. Correct anything that's out of date — no need to repeat what's already here."},{"id":"people","title":"Your team","intro":"Who's involved, and how much time this takes today."},{"id":"tools","title":"Tools you use today","intro":"Check everything you use, even lightly. Then tell us a bit more about the few that matter most for this project."},{"id":"ai","title":"AI today","intro":"No wrong answers — plenty of teams are just getting started."},{"id":"history","title":"What you've tried","intro":"This helps us avoid suggesting things you've already ruled out."},{"id":"workflow_content","title":"Your content workflow","intro":"Walk us through how a post goes from idea to published."},{"id":"workflow_fundraising","title":"Your fundraising and donor workflow","intro":"How donor information and outreach work today."},{"id":"workflow_data","title":"Your data and reporting","intro":"What you track, and how reports get made."},{"id":"workflow_general","title":"The process you want to improve","intro":"Walk us through the process as it actually happens today."},{"id":"data_sensitivity","title":"Data and constraints","intro":"So we can recommend tools that fit your obligations."},{"id":"success","title":"What success looks like","intro":"Last section."}]$j$::jsonb, true);
