  ('719d6e12-6cb0-5ba5-b864-7937d9c69ced', 'Small Nonprofit: Productivity & Integration', 'Microsoft 365, meetings and scheduling, and a daily command center for small nonprofits.', 'A few questions about your team, the tools you use today, what you''ve already tried and what a useful daily summary would look like. It takes about 10 minutes and saves as you go, so you can stop and come back with the same link.', 10, $j$[{"id":"organization","title":"Organization"},{"id":"current_tools","title":"Current tools"},{"id":"past_attempts","title":"Past attempts"},{"id":"meetings","title":"Meetings and scheduling"},{"id":"command_center","title":"Command center"},{"id":"data_ownership","title":"Data and ownership"},{"id":"success","title":"Success"}]$j$::jsonb);
